import {requireVendorManager} from '@/lib/auth/vendor';import {createProduct} from '@/app/vendor/actions';import {getVendorCategories,getVendorMedia} from '@/services/vendor-dashboard';import {VendorProductForm} from '@/components/vendor-product-form';
export default async function NewProductPage(){const context=await requireVendorManager();const[categories,media]=await Promise.all([getVendorCategories(),getVendorMedia(context.userId,context.restaurant!.id)]);return <><div className="vendor-page-head"><div><p className="section-kicker">Nouveau produit</p><h1>Ajouter un produit</h1><p>Une photo, un nom, un prix : l’essentiel seulement.</p></div></div><VendorProductForm action={createProduct} categories={categories} media={media} restaurantId={context.restaurant!.id}/></>}
